D[6865]={"^Generating |cffff7f7fHeat|r now has a (.-)%% chance to grant |cffffffffFlamecasting|r%.%s*$","Gerar |cffff7f7fCalor|r agora tem {{1}}% de chance de conceder |cffffffffConjuração de Chamas|r."}
D[7056]={"^Emanate the |cffffffffPestilence of Apocalypse|r, causing targets within (.-) yds to take (.-)%% increased Fire damage from you%.\n\n|cffffffffUnleash|r: Deal (.-) Fire damage plus an additional (.-) every (.-) sec to nearby enemies in a (.-) yd radius for (.-)%.%s*$","Emana a |cffffffffPestilência do Apocalipse|r, fazendo os alvos em um raio de {{1}} m receberem {{2}}% a mais de dano de Fogo causado por você.\n\n|cffffffffLiberar|r: causa {{3}} de dano de Fogo e mais {{4}} a cada {{5}} s aos inimigos próximos em um raio de {{6}} m durante {{7}}."}
