D[28363]={"^|cFF66DDFFLevel 10 Passive|r\nYou now have |cffffffffBreath Charges|r, allowing you to cast powerful |cffffffffBreath|r attacks%.\n\nYour |cFFFFFFFFFlare Bolt|r now has a 15 yd range and is castable while moving%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAgora tem |cffffffffCargas Respiratórias|r, o que permite que você lançar poderosos ataques de |cffffffffFôlego|r.\n\nSeu |cFFFFFFFFSeta de Labareda|r agora tem um alcance de 15 m e pode usá enquanto se movimenta."}
D[29321]={"^Dealing damage with an ability or spell grants you a stack of |cFFFFFFFFMeteoric Impact|r, upon reaching (.-) stacks you can unleash a |cFFFFFFFFFel Meteor|r%.%s*$","Causar dano com uma habilidade ou feitiço concede a você um acúmulo de |cFFFFFFFFImpacto Meteórico|r, ao alcançar {{1}} acúmulos pode libertar um |cFFFFFFFFMeteorito Vil|r."}
D[29322]={"^Dealing damage with an ability or spell grants you a stack of |cFFFFFFFFMeteoric Impact|r, upon reaching (.-) stacks you can unleash a |cFFFFFFFFFel Meteor|r%.\n\nGenerating |cFFFFFFFFMeteoric Impact|r stacks can only occur once per second%.%s*$","Causar dano com uma habilidade ou feitiço concede a você um acúmulo de |cFFFFFFFFImpacto Meteórico|r, ao alcançar {{1}} acúmulos pode libertar um |cFFFFFFFFMeteorito Vil|r.\n\nA geração de |cFFFFFFFFImpacto Meteórico|r Só pode ocorrer uma vez por segundo."}
D[29323]={"^|cFFFFFFFFYou learn this spell%.|r\nCalls down a fel meteor to the target area, dealing (.-) Magic damage and increasing your chance to score a critical strike and increasing the damage taken from the caster on targets hit by (.-)%% for (.-)%.\n\nRequires |cFFFFFFFFFel Meteor!|r to be active%.%s*$","|cFFFFFFFFAprendes este feitiço.|r\nChama um meteorito de fogo à área-alvo, causando {{1}} de dano mágico e aumenta sua chance de acerto crítico e o dano recebido conjurador em alvos afetados em {{2}}% durante {{3}}.\n\nRequer que |cFFFFFFFFMeteorito Vil!|r estiver ativo."}
D[29324]={"^|cFFFFFFFFYou learn this spell%.|r\nCalls down a fel meteor to the target area, dealing (.-) Magic damage and increasing your chance to score a critical strike and increasing the damage taken from the caster on targets hit by (.-)%% for (.-)%.\n\nRequires |cFFFFFFFFFel Meteor!|r to be active%.\n\n|nMagic damage is a combination of the Holy, Fire, Nature, Frost, Shadow and Arcane schools, and will benefit from the highest modifier to either school%.%s*$","|cFFFFFFFFAprendes este feitiço.|r\nChama um meteorito de fogo à área-alvo, causando {{1}} de dano mágico e aumenta sua chance de acerto crítico e o dano recebido conjurador em alvos afetados em {{2}}% durante {{3}}.\n\nRequer que |cFFFFFFFFMeteorito Vil!|r estiver ativo.\n\n|nO dano mágico é uma combinação das escolas Sagrado, Fogo, Natureza, Gelo, Sombras e Arcano, e se beneficiará do modificador mais alto a qualquer destas escolas."}
D[30795]={"^Trigger a Meteor Strike dealing (.-) Fire damage up to (.-) nearby targets%.%s*$","Desencadeia um Acerto de Meteorito que causa {{1}} de dano de Fogo até {{2}} alvos próximos."}
