D[41415]={"^Damage dealt by |cffffffffLava Shard|r now deals an additional 25%% of the damage dealt over (.-) as Fire damage to the target and up to 2 nearby enemies%.%s*$","O dano causado por |cffffffffFragmento de Lava|r passa a causar, ao longo de {{1}}, 25% do dano causado como dano de Fogo adicional ao alvo e a até 2 inimigos próximos."}
D[41624]={"^Breath superheated flames in a cone in front of you that melts the weapons of affected enemies, disarming their melee and ranged weapons for (.-)%.%s*$","Respira chamas supercalentadas em um cone à sua frente que fundido as armas dos inimigos afetados, desarmando-os tanto de corpo a corpo como à distância durante {{1}}."}
D[41761]={"^Root enemies in a (.-) yd line for (.-) and then soar forward in a blaze of glory, dealing (.-) Fire damage every (.-) sec to enemies beneath you for (.-)%.%s*$","Imobiliza os inimigos em uma linha de {{1}} m durante {{2}}, depois você eleva para a frente com um estalhido glorioso, causando {{3}} de dano de Fogo aos inimigos que há baixo terra a cada {{4}} s durante {{5}}."}
D[41762]={"^Soaring%.%s*$","Asas emprestadas."}
D[41765]={"^Increases the damage or healing done by |cffffffffLava Shard|r and |cffffffffCinderheart|r by (.-)%% for each Pyromancer periodic effect on the target%. Lasts (.-)%.%s*$","Aumenta o dano ou a cura de |cffffffffFragmento de Lava|r e |cffffffffCoração de Cinzas|r em {{1}}% para cada efeito periódico de Piromante no alvo. Dura {{2}}."}
