D[41922]={"^Grants 5 Flamecasting stacks upon casting Sunstrider Array%.%s*$","Proporciona 5 acúmulos de Conjuração de Chamas ao lançar Matriz Sunstrider."}
D[42535]={"^Increases the spell haste of all party and raid members by (.-)%%%. Does not stack with similar effects%.\n\nIn addition, your spell haste is increased by (.-)%%%.%s*$","Aumenta a aceleração com feitiços de todos os membros do grupo e da raide em {{1}}%. Não acumula com efeitos semelhantes.\n\nAlém disso, sua aceleração com feitiços aumenta em {{2}}%."}
D[42980]={"^Healing done by |cffffffffEmber Touch|r now grants you |cffffffffFlamecasting|r%.%s*$","A cura realizada por |cffffffffToque de Brasa|r agora concede a você |cffffffffConjuração de Chamas|r."}
D[43144]={"^Damage dealt by your |cffffffffLava Shard|r now additionally scales with your critical strike rating%.%s*$","O dano causado por seu |cffffffffFragmento de Lava|r agora escala adicionalmente com seu índice de acerto crítico."}
D[43146]={"^Increases the targets damage taken from your periodic effects by (.-)%% stacking (.-) times%.%s*$","Aumenta a quantidade dano que recebe o alvo de seus efeitos periódicos em {{1}}%, acumulando-se {{2}} vezes."}
