D[44817]={"^|cffffffffInscription: Pyroclasm|r and |cffffffffInscription: Sorcerery|r now blast 10 enemies within (.-) yds, dealing (.-) additional Spellfire Damage%.%s*$","|cffffffffInscrição: Piroclasma|r e |cffffffffInscrição: Feitiçaria|r agora atingem 10 inimigos em um raio de {{1}} m, causando {{2}} de dano de Fogo Mágico adicional."}
D[44899]={"^|cFF66DDFFLevel 20 Passive|r\nYour |cffffffffInferno Barrier|r now triggers a (.-) sec reduced cooldown when used on an ally other than yourself%.%s*$","|cFF66DDFFPassivo de Nível 20|r\nSeu |cffffffffBarreira infernal|r agora ativa um recorte na recarga de {{1}} s quando usada sobre um aliado que não seja você."}
