D[45018]={"^|cFF66DDFFLevel 15 Passive|r\nIncreases your healing spell power by (.-)%% of Spirit%.%s*$","|cFF66DDFFPassivo de Nível 15|r\nAumenta seu Poder Mágico de cura em {{1}}% do Espírito."}
D[45175]={"^Generating |cffffffffHeat|r now has a (.-)%% chance to increase the healing of your next |cffffffffEmber Touch|r within 10 sec by 25%%%.%s*$","Gerar |cffffffffCalor|r tem agora {{1}}% de chance de aumentar a cura de seu próximo |cffffffffToque de Brasa|r em 10 s em um 25%."}
D[45348]={"^Upon |cFFFFFFFFScalding Brand's|r expiration, your next |cFFFFFFFFScalding Brand|r is instant cast%.%s*$","Ao expirar |cFFFFFFFFMarca Escaldante's|r, seu próximo |cFFFFFFFFMarca Escaldante|r é de lançamento instantâneo."}
