D[90099]={"^Sacrifices the caster's life in order to inflict Arcane damage to nearby enemies%.%s*$","Sacrifica a vida do conjurador para causar dano Arcano aos inimigos próximos."}
D[90100]={"^Sacrifices the caster's life in order to inflict (.-) Arcane damage to nearby enemies%.%s*$","Sacrifica a vida do conjurador para causar {{1}} de dano Arcano aos inimigos próximos."}
