T[99]={"^(.-) Shadowflame damage every (.-) seconds%.%s*$","{{1}} dano de Chama Sombria a cada {{2}} segundos."}
T[174]={"^Enemies who stand in the fire are disoriented%.%s*$","Inimigos que permanecerem no fogo ficam desorientados."}
T[203]={"^Increases the damage of the |cffffffffUnleash|r effect of |cffffffffPestilence of Apocalypse|r by (.-)%% and its duration is increased by (.-) sec%.%s*$","Aumenta em {{1}}% o dano do efeito |cffffffffLiberar|r de |cffffffffPestilência do Apocalipse|r e aumenta sua duração em {{2}} s."}
T[313]={"^Fire Damage dealt grants |cffffffffDragonscales|r for (.-)%.|r%s*$","O dano de Fogo causado concede |cffffffffEscamas de Dragão|r durante {{1}}.|r"}
T[424]={"^Being struck with a blast of molten slag every (.-) sec%.%s*$","Você sofre um acerto com uma rajada de escória fundida a cada {{1}} s."}
T[425]={"^This unit will explode after (.-)%.%s*$","Esta unidade explodirá depois de {{1}}."}
T[679]={"^Increases the damage caused by |cffffffffInfernus|r by (.-)%%%.%s*$","Aumenta o dano causado por |cffffffffInfernus|r em {{1}}%."}
T[681]={"^|cffffffffDestroyer's Maw|r now blasts up to (.-) nearby enemies for (.-) Fire damage when used on targets affected by |cffffffffBreath of Malygos|r or |cffffffffBlaze|r%.\n\nThis triggers twice on enemies affected by both |cffffffffBreath of Malygos|r and |cffffffffBlaze|r%.%s*$","|cffffffffGorja do Destruidor|r agora atinge até {{1}} inimigos próximos, causando {{2}} de dano de Fogo quando usada contra alvos afetados por |cffffffffSopro de Malygos|r ou |cffffffffLabareda|r.\n\nO efeito é ativado duas vezes contra inimigos afetados pelos dois efeitos."}
T[694]={"^|cffffffffCinderheart|r and |cffffffffLava Shard|r now reduces the cooldown of |cffffffffTide of Fire|r and |cffffffffSunstrider Array|r by (.-) sec%.%s*$","|cffffffffCoração de Cinzas|r e |cffffffffFragmento de Lava|r agora reduzem a recarga de |cffffffffOnda de Fogo|r e |cffffffffMatriz Sunstrider|r em {{1}} s."}
T[1179]={"^|cffffffffLava Shard|r is now guaranteed to critically strike%.%s*$","Agora |cffffffffFragmento de Lava|r está garantido a acerto crítico."}
T[1279]={"^Immoblized%. Increasing the damage of your |cffff7f7fEmber|r spenders by (.-)%% and causing them to strike up to (.-) additional enemies%.%s*$","Imobilizado. Aumenta o dano de seus |cffff7f7fBrasa|r em {{1}}% e Faz com que atinjam até {{2}} inimigos adicionais."}
T[1444]={"^|cffffffffFlare Bolt|r increases your movement speed by (.-)%% for (.-), stacking 4 times%.\n\n|cffffffffLava Shard|r consumes the stacks to deal (.-) bonus damage and reduce movement speed by (.-)%%%.\n\nDamage increased by (.-)%%, movement speed reduction by 5%% and duration increased by (.-) sec per stack consumed%.%s*$","|cffffffffSeta de Labareda|r aumenta sua velocidade de movimento em {{1}}% por {{2}}, acumulando até 4 vezes.\n\n|cffffffffFragmento de Lava|r consome os acúmulos para causar {{3}} de dano adicional e reduzir a velocidade de movimento em {{4}}%.\n\nPara cada acúmulo consumido, o dano aumenta em {{5}}%, a redução da velocidade de movimento aumenta em 5% e a duração aumenta em {{6}} s."}
T[1445]={"^Flying%. Cannot stop moving%.\n\nEvery (.-) sec while active, you will launch a molten boulder upon the nearest enemy down below you, dealing massive Fire Damage%.%s*$","Voo. Você não pode parar de se mover.\n\nA cada {{1}} s enquanto estiver ativo, você lança uma rocha fundida sobre o inimigo mais próximo abaixo de você, causando dano massivo de Fogo."}
T[1446]={"^Increases your spell damage by (.-)%% of your Intellect and your critical damage with spells by (.-)%%%.\n\nDirect damage dealt launches Dragon's Wrath at your target%.%s*$","Aumenta seu dano mágico em {{1}}% de seu Intelecto e aumenta seu dano crítico com feitiços em {{2}}%.\n\nO dano direto lançado lança Raiva do Dragão contra seu alvo."}
T[1454]={"^Increases the cooldown of your |cffffffffBreaths|r by (.-) sec, and gives them a (.-) sec cast time, but increases their damage by (.-)%%%.%s*$","Reduz a recarga de seus |cffffffffrespirações|r em {{1}} s e lhes da um tempo de lançamento de {{2}} s, mas aumenta seu dano em {{3}}%."}
T[1503]={"^Your Lava Shard ability now grants Replenishment to all nearby party and raid members, restoring a portion of their Mana over time%.\n\nThis cannot occur more than once every 10 sec%.%s*$","Sua habilidade Fragmento de Lava agora concede Recuperação todos os membros próximos do grupo e da raide, restaurando uma parte de sua mana com o passo do tempo.\n\nIsto não pode acontecer mais de uma vez a cada 10 s."}
T[1506]={"^Increases the Duration of your Ignite, Blaze and Scalding Brand spells by (.-)%%%.%s*$","Aumenta a Duração de seus Ignição, Brasa e Marca Escaldante em {{1}}%."}
T[1549]={"^Periodically generates an Ember and Cinderheart generates double the amount of Heat%.%s*$","Gera periodicamente uma Brasa, e Coração de Cinzas gera o dobro de Calor."}
T[1561]={"^Fire damage critical strikes now grant |cffffffffFlamecasting|r%.%s*$","Agora os acertos críticos de dano de Fogo concedem |cffffffffConjuração de Chamas|r."}
T[1643]={"^Emanating a pestilence, causing targets within (.-) yds to take (.-)%% increased Fire damage%.%s*$","Emanando uma peste, fazendo com que as vítimas em um raio de {{1}} m recebam um aumento de {{2}}% no dano por Fogo."}
T[1651]={"^Allows Lava Shard to strike up to (.-) enemies%.%s*$","Permite que Fragmento Lava golpeie até {{1}} inimigos."}
T[1766]={"^Causes your Fire Critical Strikes to grant Flamecasting, creating a Path of Flames under the target, and increasing you Spell Haste by (.-)%% for (.-), stacks up to 3 times%.\n\nIn addition, your Fire Spells cost (.-)%% reduced Mana, but each time you cast a Fire spell, you gain a stack of Overheating for (.-), increasing the cost of your Fire Spells by (.-)%% and increasing your Spell Critical Strike Rating by (.-)%% of your Intellect%. Stacks up to (.-) times%.\n\nAlso allows (.-)%% of your Mana Regeneration to continue while casting%.%s*$","Seus acertos críticos de Fogo concedem |cffffffffConjuração de Chamas|r, criando um Caminho de Chamas sob o alvo e aumentando sua Aceleração de Feitiços em {{1}}% durante {{2}}, acumulando até 3 vezes.\n\nAlém disso, seus feitiços de Fogo custam {{3}}% menos mana. Sempre que você lança um feitiço de Fogo, recebe um acúmulo de Superaquecimento durante {{4}}, aumentando em {{5}}% o custo dos seus feitiços de Fogo e em {{6}}% do seu Intelecto sua índice de acerto crítico com feitiços. Acumula até {{7}} vezes.\n\nTambém permite que {{8}}% da sua regeneração de mana continue durante a conjuração."}
T[1908]={"^Damage dealt by |cffffffffExplode|r now reduces the cooldown of |cffffffffPillar of Flame|r by (.-) sec%.%s*$","O dano causado por |cffffffffExplodir|r agora reduz a recarga de |cffffffffColuna de chamas|r em {{1}} s."}
T[2061]={"^Deals Fire damage every (.-) sec%.\nReduces healing taken%.%s*$","Causa dano de Fogo a cada {{1}} s.\nReduz a cura recebida."}
T[2991]={"^(.-) Fire damage dealt every (.-) seconds%.%s*$","{{1}} dano de Fogo a cada {{2}} segundos."}
T[3279]={"^Don't look up!%s*$","Não olhe para cima!"}
T[3315]={"^Dealing Fire damage%.%s*$","Causar dano de Fogo."}
T[3356]={"^Taking (.-) Fire damage every (.-) seconds%.%s*$","Recebe {{1}} dano de Fogo a cada {{2}} segundos."}
T[3393]={"^Reduces the cast time of Flamestrike by (.-)%% and reduces its mana cost by (.-)%%%.%s*$","Reduz o tempo de lançamento de Coluna de Chamas em {{1}}% e reduz seu custo de mana em {{2}}%."}
T[3417]={"^Your Starfall is transformed into Firefall%.%s*$","Seu Chuva Estelar transforma-se em Chuva de Fogo."}
T[3418]={"^Summoning fiery stars from the sky%.%s*$","Invocas estrelas de fogo do céu."}
T[3419]={"^You summon a flurry of fire stars from the sky on all targets within 30 yards of the caster, each dealing (.-) Fire damage%. Also causes (.-) Fire damage to all other enemies within (.-) yards of the enemy target%. Maximum 20 stars%. Lasts (.-)%.%s*$","Evoca uma chuva de estrelas de fogo do céu sobre todos os alvos em um raio de 30 m do conjurador, cada uma causando {{1}} de dano de Fogo. Também causa {{2}} de dano de Fogo a todos os outros inimigos em um raio de {{3}} m do alvo. Máximo de 20 estrelas. Dura {{4}}."}
T[3647]={"^You're being burned alive!%s*$","Está sendo queimado vivo!"}
T[3720]={"^Burning for (.-) Fire damage every (.-) seconds%.%s*$","Queimando e causando {{1}} de dano de Fogo a cada {{2}} segundos."}
T[3721]={"^Causes (.-) Fire Damage every (.-) sec%.%s*$","Causa {{1}} de dano de Fogo a cada {{2}} s."}
T[3844]={"^Damage of your next direct spell increased by (.-)%%%.%s*$","O dano de seu próximo feitiço direto aumenta em {{1}}%."}
T[3879]={"^Damage dealt by Lava Shard and Flare Bolt increased by (.-)%% on targets below 35%% maximum health%.%s*$","O dano causado por Pedrisco de lava e Relâmpago flamejante aumenta em {{1}}% em alvos com menos de 35% de vida máxima."}
T[3975]={"^Your next Lava Shard doesn't incur a cooldown and costs (.-)%% less mana%.%s*$","Seu próximo Fragmento de Lava não tem recarga e custa {{1}}% menos mana."}
T[4031]={"^Taking (.-) Fire damage every (.-) sec%. Fire attacks against this target have (.-)%% increased critical strike chance%.%s*$","Recebe {{1}} de dano de Fogo a cada {{2}} s. Os ataques de Fogo contra este alvo têm um aumento de {{3}}% na chance de acerto crítico."}
T[4037]={"^Damage from the Pyromancer's Ignite increased by (.-)%%%.%s*$","O dano causado pela Ignição do piromante aumenta em {{1}}%."}
T[4239]={"^Absorbing damage%. Channeling to end the world%.%s*$","Absorve dano. Canalizando para acabar com o mundo."}
T[4297]={"^Burning for (.-)%% of the initial damage of Scorch over (.-)%.%s*$","Queimando em {{1}}% do dano inicial de Queima sobre {{2}}."}
T[4299]={"^Critical strike chance of your |cffffffffLava Shard|r, |cffffffffExplode|r, or |cffffffffFlare Bolt|r increased by (.-)%% until one of these abilities critically strike%.%s*$","A chance de acerto crítico de |cffffffffFragmento de Lava|r, |cffffffffExplodir|r ou |cffffffffSeta de Labareda|r aumenta em {{1}}% até um desses feitiços causar um acerto crítico."}
T[4345]={"^Damage of next Destroyer's Maw increased by (.-)%%%.%s*$","O dano do próximo Agarrão do Destruidor aumenta em {{1}}%."}
T[4346]={"^Healing done by the Pyromancer's Lantern Tender increased by (.-)%%%.%s*$","A cura realizada pelo Guardião da Lanterna do Piromante aumenta em {{1}}%."}
T[4385]={"^Increases fire damage you deal to enemies stunned by |cffffffffPetrifying Visage|r by (.-)%%%.%s*$","Aumenta o dano de Fogo que causa os inimigos atordoados por |cffffffffSemblante Petrificante|r em {{1}}%."}
T[4386]={"^Fire damage from the Pyromancer increased by (.-)%%%.%s*$","O dano de Fogo do Piromante aumenta em {{1}}%."}
T[4492]={"^Healing of next Cinderheart or Ember Touch increased by (.-)%%%s*$","A cura do próximo Latir do coração ou Toque de Brasa aumenta em {{1}}%"}
T[4528]={"^Your next Flare Bolt is instant cast%.%s*$","Seu próximo Projétil Incendiário será lançado instantaneamente."}
T[4530]={"^All periodic damage dealt now gives you a (.-)%% chance to cast |cffffffffMagmaspike|r beneath the target free of cost%.%s*$","Todo dano periódico causado concede {{1}}% de chance de lançar |cffffffffEspinho de Magma|r sob o alvo sem custo."}
T[4606]={"^Suffering (.-) Arcane Damage every 3 seconds%. Magic Damage dealt reduced by (.-)%%%. Healing taken reduced by (.-)%%%.%s*$","Sofre {{1}} de dano Arcano a cada 3 s. O dano mágico causado é reduzido em {{2}}%. A cura recebida é reduzida em {{3}}%."}
T[4611]={"^Taking (.-)%% of your maximum health as Fire damage every (.-) seconds%.%s*$","Recebe {{1}}% de sua vida máxima como dano de Fogo a cada {{2}} segundos."}
T[4690]={"^Taking (.-) Fire damage every (.-) sec%. Fire attacks against this target have (.-)%% increased Critical Strike Chance%.%s*$","Recebe {{1}} dano de Fogo a cada {{2}} s. Os ataques de Fogo contra este alvo têm um aumento do {{3}}% na chance de acerto crítico."}
T[4743]={"^Armor reduced by (.-)%%%.%s*$","Armadura reduzida em {{1}}%."}
T[4755]={"^Armor increased by (.-)%% of Intellect%. Damage taken reduced by (.-)%%%.\n\nDealing bonus Fire Damage on spellcast%.%s*$","Armadura aumentada em {{1}}% do Intelecto. Dano recebido reduzido em {{2}}%.\n\nCausa dano de Fogo adicional ao lançar feitiços."}
T[4806]={"^Spell haste increased by (.-)%%%. Spirit increased by (.-)%%%.Stacks (.-) times%.%s*$","Aumenta a aceleração com feitiços em {{1}}%. Espírito aumenta em {{2}}%. Acumula {{3}} vezes."}
T[4807]={"^Spell haste increased by (.-)%%%. Stacks (.-) times%.%s*$","Aumenta a aceleração com feitiços em {{1}}%. Acumula {{2}} vezes."}
T[4809]={"^Fire Damage critical strikes now grant |cffffffffFlamecasting|r%.%s*$","Os acertos críticos de dano de Fogo agora concedem |cffffffffConjuração de Chamas|r."}
T[4814]={"^Immune to Stun, Silence and Interrupt effects%.%s*$","Imune aos efeitos de Atordoamento, Silenciar e Interromper."}
