T[15861]={"^Inflicts (.-) Fire damage to all enemies in the selected area, burning the ground, inflicting an additional (.-) Fire damage every second for up to (.-)%.%s*$","Causa {{1}} de dano de Fogo a todos os inimigos na área selecionada, incendiando o chão e causando mais {{2}} de dano de Fogo a cada segundo por até {{3}}."}
T[15952]={"^A Infernal Meteor crashes down, inflicting massive Fire damage to all enemies in the impact area, split between all targets hit%.\n\nDamage increases with the total number of player inside the raid%.%s*$","Um Meteoro Infernal cai violentamente, causando grande quantidade de dano de Fogo a todos os inimigos na área de impacto, dividido entre todos os alvos atingidos.\n\nO dano aumenta conforme o número total de jogadores na raide."}
T[16016]={"^Heralds the coming of the end%.\n\nUpon reaching 10 stacks of Apocalypse the Horsemen will end all life%.%s*$","Anuncia o fim que se aproxima-se.\n\nAo alcançar 10 acúmulos de Apocalipse, os Maldições colocarão um fim a todas as vidas."}
T[16017]={"^Calls forth the Apocalypse, ending all life%.%s*$","Invoca o Apocalipse, exterminando toda a vida."}
T[16247]={"^Increases your spell power by (.-) when fighting Dragonkin%.%s*$","Aumenta seu Poder Mágico em {{1}} ao lutar contra Bichos Dragão."}
T[16880]={"^Calls a meteor on a player%s*$","Evoca um meteorito sobre um jogador."}
T[16888]={"^Summon Meteor%s*$","evocar Meteoro."}
T[17103]={"^Building up a Fel Surge%. Resets the cooldown of Fel Meteor, Fel Strike and Unleash Fel Energy upon reaching 5 stacks%.%s*$","Acumulando um Impacto de Felo. Reinicia a recarga de Meteorito de Felo, Golpe de Felo e Desatar Energia de Felo ao alcançar 5 acúmulos."}
T[17117]={"^nature meteor proc sls for 271284%s*$","meteorito de natureza ativação sls para 271284"}
T[17118]={"^frost meteor proc sls for 271284%s*$","proc de meteoro Gelo sls para 271284"}
T[17119]={"^arcane meteor proc sls for 271284%s*$","proc de meteoro Arcano sls para 271284"}
T[17124]={"^You are infused with fel power%. When you deal damage you have a chance to call down a fel meteor to the target area, dealing Chaos damage and increasing your chance to score a critical strike on targets hit by 5%% for 10 seconds%.%s*$","Você é infundido com poder vil. Ao causar dano, há uma chance de invocar um meteoro vil na área do alvo, causando dano de Caos e aumentando em 5% sua chance de acerto crítico contra os alvos atingidos durante 10 s."}
T[17902]={"^Fire Damage from the Pyromancer increased by (.-)%%%. Stacks (.-) times%.%s*$","O dano de Fogo do Mago de fogo aumenta em {{1}}%. Acumula {{2}} vezes."}
T[18334]={"^Once getting 3 Essences, you fire a Pillar of Flame at the target%.%s*$","Uma vez obtidas 3 Essenciais, lança uma Coluna de Fogo o alvo."}
T[18606]={"^Soaring%.%s*$","Asas emprestadas."}
T[19054]={"^A meteor is launched towards you every 15 seconds%.%s*$","Um meteorito se lança até você a cada 15 segundos."}
T[19162]={"^Cooldown of Dragonfire reduced by %$/1000s1 seconds%.%s*$","A recarga de |cffffffffFogo de Dragão|r é reduzida em $/1000s1 segundos."}
T[19244]={"^Movement speed increased by (.-)%%%. Stacks up to 4 times%.\n\nYour next Lava Shard consumes these stacks to deal (.-) Fire Damage and reduce movement speed by (.-)%%%.%s*$","Velocidade de movimento aumentada em {{1}}%. Acumula até 4 vezes.\n\nSeu próximo Fragmento Lava consome esses acúmulos para causar {{2}} dano de Fogo e reduzir a velocidade de movimento em {{3}}%."}
T[19262]={"^Scoring 3 critical strikes with |cffffffffLava Shard|r or |cffffffffBreath of Neltharion|r within (.-) now resets the cooldown of |cffffffffDestroyer's Maw|r and grants you |cffffffffDeathwing's Revenge|r%.%s*$","Marcar 3 acertos críticos com |cffffffffFragmento de Lava|r ou |cffffffffSopro de Neltharion|r em um raio de {{1}} agora reinicia a recarga de |cffffffffGorja do Destruidor|r e concede a você |cffffffffVingança de Asa da Morte|r."}
T[19293]={"^Movement speed slowed by (.-)%% and the duration of stun and root effects on you is increased by (.-)%%%.\n\nAfter 1 sec you will be pulled towards the Pyromancer and at the end of the duration everyone in the radius will explode!%s*$","Sua velocidade de movimento é reduzida em {{1}}% e a duração dos efeitos de Atordoamento e Enraizamento em você aumenta em {{2}}%.\n\nApós 1 s, você será puxado em direção ao Piromante e, ao fim da duração, todos dentro do raio explodirão!"}
T[19409]={"^Your next 2 Lava Shards incur no cooldown, become instant cast, and reduce the cooldown of Pillar of Flame by 2 sec%.%s*$","Seus próximos 2 Fragmento de Lava não tem recarga, se volta instantâneo e reduz a recarga do Pilar de Flamas em 2 s."}
T[19410]={"^At 3 stacks your next Destroyer's Maw deals (.-)%% increased damage%.%s*$","Com 3 acúmulos seu próximo Destruidor de Mandíbulas causa dano aumentado em {{1}}%."}
T[19411]={"^At 2 stacks your next Destroyer's Maw deals (.-)%% increased damage%.%s*$","Com 2 acúmulos seu próximo Destruidor de Mandíbulas causa dano aumentado em {{1}}%."}
T[20460]={"^Legacy of the Arcanist %- Meteor %(ICD%)%s*$","Legado do Arcanista - Meteorito (ICD)."}
T[20490]={"^Grants Decimation upon hitting 3 stacks%.%s*$","Concede Decimação ao alcançar 3 acúmulos."}
T[20958]={"^Chance on damage dealt to fire a meteor at an enemy%.\n\nStacks up to 5 times%.%s*$","Ao causar dano, você tem chance de disparar um meteoro contra um inimigo.\n\nAcumula até 5 vezes."}
T[21375]={"^Calls down a meteor upon the target, inflicting (.-) Fire damage to the target and all other surrounding enemies upon impact and burns the ground for an additional (.-) Fire damage every second for (.-)%.%s*$","Invoca um meteorito sobre o alvo, causando {{1}} de dano de Fogo ao alvo e a todos os inimigos próximos no impacto, além de incendiar o solo e causar {{2}} de dano de Fogo adicional a cada segundo por {{3}}."}
T[21415]={"^Calls down a meteor upon the target, inflicting (.-) Fire damage to the target and all other surrounding enemies upon impact and burns the ground for an additional (.-) Fire damage every second for (.-)%.%s*$","Invoca um meteorito sobre o alvo, causando {{1}} de dano de Fogo ao alvo e a todos os inimigos próximos no impacto, além de incendiar o solo e causar {{2}} de dano de Fogo adicional a cada segundo por {{3}}."}
